#include "../src/frame_bridge.hpp"
#include <iostream>
using namespace arc;
static void require(bool condition,const char* text){if(!condition)throw std::runtime_error(text);}
int wmain(int argc,wchar_t** argv){CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);if(argc==4&&std::wstring(argv[1])==L"--collector"){int result=runCollector(wcstoul(argv[2],nullptr,10),_wcstoui64(argv[3],nullptr,10));CoUninitialize();return result;}try{FrameBridge bridge;require(bridge.available(),"shared mapping");bridge.request(GetCurrentProcessId(),2);wchar_t path[32768]{};GetModuleFileName(nullptr,path,32768);std::wstring command=L"\""+std::wstring(path)+L"\" --collector "+std::to_wstring(GetCurrentProcessId())+L" "+std::to_wstring(bridge.nonce);STARTUPINFO startup{sizeof(startup)};PROCESS_INFORMATION child{};require(CreateProcessW(nullptr,command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&startup,&child)!=FALSE,"collector spawn");CloseHandle(child.hThread);std::optional<BridgeResult> result;for(int i=0;i<40;++i){result=bridge.read();if(result&&result->target==GetCurrentProcessId()&&result->seconds==2)break;Sleep(100);}require(result&&result->target==GetCurrentProcessId()&&result->seconds==2,"collector first connection without parent restart");bridge.request(GetCurrentProcessId(),4);for(int i=0;i<30;++i){result=bridge.read();if(result&&result->seconds==4)break;Sleep(100);}require(result&&result->seconds==4,"live statistics window change");bridge.request(0,4);require(WaitForSingleObject(child.hProcess,3000)==WAIT_OBJECT_0,"disabled collector exits");DWORD code=1;GetExitCodeProcess(child.hProcess,&code);CloseHandle(child.hProcess);require(code==0,"collector clean exit");std::cout<<"Bridge live connection, reconfiguration and shutdown passed; ETW status="<<result->error<<"\n";CoUninitialize();return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";CoUninitialize();return 1;}}
